/* Extra dojo rooms for index2.html. */
window.STAGES_READY = (async () => {
  window.MEDIA = window.MEDIA || {};
  const items = [
    ["dojo2.jpg","image/jpeg",""],
    ["dojo3.jpg","image/jpeg",""],
  ];
  function toUrl(mime, b64) {
    const bin = atob(b64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return URL.createObjectURL(new Blob([bytes], { type: mime }));
  }
  const total = items.length;
  for (let i = 0; i < total; i++) {
    const row = items[i];
    const name = row[0];
    if (window.notePackedFile) window.notePackedFile(name, i, total, "stages");
    else {
      const el = document.getElementById("loadstate");
      if (el) el.textContent = "Preparing " + name + "  ·  " + (i + 1) + " / " + total;
    }
    await new Promise((resolve) => requestAnimationFrame(() => setTimeout(resolve, 16)));
    window.MEDIA[name] = toUrl(row[1], row[2]);
    items[i] = null;
  }
})();
